export function AppleGalleryDemo() {
  return (
    <AppleGallery>
      <AppleGalleryContainer className="h-160">
        {IPHONE_FEATURE_IMAGES_PROPS.map((props) => (
          <Card key={props.alt} className="relative overflow-hidden">
